const MAX_FRAME_BYTES = 256 * 1024;
const MAX_CHUNK_BYTES = 192;
const MAX_INFLIGHT = 64;
const MAX_PARTIAL_BYTES = 8 * 1024 * 1024;
const MAX_AGE_MS = 30_000;
const UUID = /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i;

/** Atomic FD 3 fragments are reassembled separately for each opaque message id. */
export function createNativeModelTraceFrameDecoder(options: { now?: () => number } = {}) {
  const partials = new Map<
    string,
    { part: number; startedAt: number; bytes: number; chunks: Buffer[] }
  >();
  let partialBytes = 0;
  const remove = (id: string) => {
    const partial = partials.get(id);
    if (partial) partialBytes -= partial.bytes;
    partials.delete(id);
  };
  const invalid = (): never => {
    throw new Error("Invalid native model observation fragment");
  };
  return {
    read(line: string): string | undefined {
      if (Buffer.byteLength(line) > MAX_FRAME_BYTES) invalid();
      const value = JSON.parse(line);
      if (value?.type !== "model_trace_chunk") return line;
      const now = (options.now ?? Date.now)();
      for (const [id, partial] of partials) if (now - partial.startedAt > MAX_AGE_MS) remove(id);
      if (
        !value ||
        typeof value !== "object" ||
        Array.isArray(value) ||
        Object.keys(value).some(
          (key) => !["version", "type", "messageId", "part", "data", "final"].includes(key),
        ) ||
        value.version !== 1 ||
        typeof value.messageId !== "string" ||
        !UUID.test(value.messageId) ||
        !Number.isSafeInteger(value.part) ||
        value.part < 0 ||
        value.part > Math.ceil(MAX_FRAME_BYTES / MAX_CHUNK_BYTES) ||
        typeof value.final !== "boolean" ||
        typeof value.data !== "string" ||
        !value.data ||
        value.data.length > 256 ||
        Buffer.byteLength(line) + 1 > 512 ||
        !/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(value.data)
      )
        invalid();
      const bytes = Buffer.from(value.data, "base64");
      if (
        !bytes.length ||
        bytes.length > MAX_CHUNK_BYTES ||
        bytes.toString("base64") !== value.data
      )
        invalid();
      let partial = partials.get(value.messageId);
      if (!partial) {
        if (value.part !== 0 || partials.size >= MAX_INFLIGHT) invalid();
        partial = { part: 0, startedAt: now, bytes: 0, chunks: [] };
        partials.set(value.messageId, partial);
      }
      if (
        value.part !== partial.part ||
        partial.bytes + bytes.length > MAX_FRAME_BYTES ||
        partialBytes + bytes.length > MAX_PARTIAL_BYTES
      )
        invalid();
      partial.part++;
      partial.bytes += bytes.length;
      partialBytes += bytes.length;
      partial.chunks.push(bytes);
      if (!value.final) return undefined;
      remove(value.messageId);
      const decoded = new TextDecoder("utf-8", { fatal: true }).decode(
        Buffer.concat(partial.chunks),
      );
      if (decoded.includes("\n") || decoded.includes("\r")) invalid();
      // Validate before returning, so a nested fragment cannot bypass parser limits.
      const message = JSON.parse(decoded);
      if (message?.type !== "model_trace") invalid();
      return decoded;
    },
    clear() {
      partials.clear();
      partialBytes = 0;
    },
  };
}

import { redactSecrets } from "../logging/sanitize-messages.js";
import type { ModelTraceContentState } from "./types.js";

const MAX_STRING = 64 * 1024;
const MAX_NODES = 12_000;
const REDACTED = "<redacted>";
const SECRET_KEY =
  /(^|[._-])(api[_-]?key|authorization|x[_-]api[_-]key|bearer[_-]?token|access[_-]?token|refresh[_-]?token|session[_-]?token|token|secret|password|client[_-]?secret|cookie)($|[._-])/i;
const HEADERS = /^(httpHeaders|headers|defaultHeaders|envHeaders)$/;

/** Provider-neutral diagnostic clone. Never mutate the actual outbound request. */
export function sanitizeTraceValue(
  value: unknown,
  redactions?: ReadonlyMap<string, string>,
): {
  value: any;
  state: ModelTraceContentState;
} {
  let truncated = false,
    redacted = false,
    nodes = 0;
  let remaining = 256 * 1024;
  const seen = new WeakSet<object>();
  const walk = (input: unknown, depth = 0): unknown => {
    if (++nodes > MAX_NODES || depth > 32) {
      truncated = true;
      return "<truncated>";
    }
    if (typeof input === "string") {
      if (/^data:(image|audio|video|application\/pdf)[^,]*,/i.test(input)) {
        redacted = true;
        return "<media payload omitted>";
      }
      let scrubbed = redactSecrets(input);
      if (/^\s*[{[]/.test(scrubbed) && scrubbed.length <= MAX_STRING) {
        try {
          scrubbed = JSON.stringify(walk(JSON.parse(scrubbed), depth + 1));
        } catch {
          /* Partial streamed JSON still needs secret scalar scrubbing below. */
        }
      }
      // Tool arguments are wire-encoded JSON strings and can fail halfway through a
      // secret value. Scrub such scalars before persisting even malformed partial JSON.
      scrubbed = scrubbed.replace(
        /"([^"\\]*(?:\\.[^"\\]*)*)"\s*:\s*("(?:[^"\\]|\\.)*(?:"|$)|[^,}\]\s]+)/g,
        (match, key: string, scalar: string) => {
          let name = key;
          try {
            name = JSON.parse(`"${key}"`);
          } catch {
            /* Use the literal key. */
          }
          if (!SECRET_KEY.test(name) || /^(null|"")$/.test(scalar)) return match;
          redacted = true;
          return `${JSON.stringify(name)}:${JSON.stringify(REDACTED)}`;
        },
      );
      if (scrubbed !== input) redacted = true;
      const length = Math.min(MAX_STRING, remaining);
      remaining -= Math.min(scrubbed.length, length);
      if (scrubbed.length > length) {
        truncated = true;
        return `${scrubbed.slice(0, length)}\n<truncated>`;
      }
      return scrubbed;
    }
    if (["bigint", "symbol", "function"].includes(typeof input)) return String(input);
    if (input === null || typeof input !== "object") return input;
    if (seen.has(input)) {
      truncated = true;
      return "<circular>";
    }
    seen.add(input);
    if (Array.isArray(input)) {
      const result = input.slice(0, 2048).map((item) => walk(item, depth + 1));
      if (input.length > 2048) truncated = true;
      seen.delete(input);
      return result;
    }
    const object = input as Record<string, unknown>;
    const callId = object.tool_use_id ?? object.tool_call_id;
    if (
      object.type === "image" ||
      object.type === "image_url" ||
      object.type === "input_image" ||
      (object.type === "base64" && typeof object.data === "string")
    ) {
      redacted = true;
      seen.delete(input);
      return {
        type: object.type,
        media_type: object.media_type ?? (object.source as any)?.media_type,
        omitted: true,
      };
    }
    const result: Record<string, unknown> = Object.create(null);
    for (const [name, child] of Object.entries(object)) {
      if (
        typeof callId === "string" &&
        redactions?.has(callId) &&
        ["content", "result", "contentBlocks"].includes(name)
      ) {
        redacted = true;
        result[name] = redactions.get(callId) ?? REDACTED;
      } else if (SECRET_KEY.test(name)) {
        if (child === null || child === undefined || child === "") result[name] = child;
        else {
          redacted = true;
          result[name] = REDACTED;
        }
      } else if (
        HEADERS.test(name) &&
        child &&
        typeof child === "object" &&
        !Array.isArray(child)
      ) {
        redacted = true;
        result[name] = Object.fromEntries(
          Object.entries(child).map(([header, value]) => [
            header,
            value === null || value === undefined || value === "" ? value : REDACTED,
          ]),
        );
      } else if (
        (name === "inline_data" || name === "inlineData") &&
        child &&
        typeof child === "object" &&
        typeof (child as any).data === "string"
      ) {
        redacted = true;
        result[name] = {
          mime_type: (child as any).mime_type ?? (child as any).mimeType,
          omitted: true,
        };
      } else if (name === "b64_json" && typeof child === "string") {
        redacted = true;
        result[name] = "<media payload omitted>";
      } else result[name] = walk(child, depth + 1);
    }
    seen.delete(input);
    return result;
  };
  return {
    value: walk(value),
    state: truncated ? "truncated" : redacted ? "redacted" : "recorded",
  };
}
